    "a": "广义表是线性表的推广，是n个元素a1,a2,...,an组成的有限序列\n若广义表LS非空（n≥1），则a1是LS的表头，其余元素组成的表（a2,...ai，...,an）称为LS的表尾\n简述广义表的深度和长度\n深度：指广义表中括号的最大层数\n广度：指广义表中所包含的数据元素的个数。\n树：是n个结点的有限集合，n≥0，只有一个根结点，根结点无前驱\n结点的度：结点拥有的子树的数量称为结点的度\n树的度：树的度是树内各结点度的最大值\n树的深度：树中结点的最大层次称为树的深度或高度\n二叉树：树中结点的度不大于2的有序树。每个结点最多只能有两棵子树，且有左右之分\n森林：m（m≥1）棵互不相交的树的集合\n满二叉树：深度为k且含有2ᴷ－1个结点的二叉树\n完全二叉树：深度为k，有n个结点的二叉树，当且仅当每一个结点都与深度为k的满二叉树中编号从1至n的结点一一对应时，称之为完全二叉树\n二叉排序树：左子树上所有的关键字均小于根结点，右子树上所有关键字均大于根结点\n平衡二叉树：数中每一个结点的左子树，右子树高度之差的绝对值小于等于1"
