    "a": "度为2的树：无序树，每个结点最多有两棵子树，且至少有一棵树有两个孩子结点\n二叉树：树中结点的度不大于2的有序树。每个结点最多有两棵子树，且有左右之分。\n二叉树的性质\n二叉树的第i层最多有2ⁱ⁻¹个结点；\n深度为k的二叉树最多有2ᵏ-1个结点；\n对任意二叉树，叶子结点总比度为2的结点多1个；\n具有n个结点的完全二叉树深度为llog₂nl+1\n二叉树的存储结构\n顺序存储：用一组连续的地址单元自上而下，自左到右的存储完全二叉树的结点元素\n链式存储：采用二叉链表来存储树的每个结点"
