    "a": "树的路径长度和树的带权路径长度?(2022)\n树的路径长度：从根结点到每一个结点的路径长度总和；\n带权路径长度：结点的路径与路径的权值乘积\n树的带权路径长度(WPL): 树中所有叶子结点的带权路径长度之和。\n哈夫曼树：带权路径长度最短的二叉树为哈夫曼树\n图：图是有顶点的有穷非空集合和顶点之间边的集合组成\n有向图(2024)：图中的每条边都是有方向的，如<x,y>和<y,x>是不同的俩条边\n有向图的度(2024)：顶点的度分为入度和出度。入度是以顶点v为终点弧的数目；出度是以顶点v为起点弧的数目，顶点的度等于入度和出度之和。\n无向图：图中每条边都是没有方向的，(x,y)和(y,x)是同一条边\n无向完全图：对于含有n个顶点的无向图，若具有n(n-1)/2条边，则称为无向完全图\n有向完全图：对于含有n个顶点的有向图，若具有n(n-1)/条弧，则称为有向完全图\n连通图：在无向图中如果两顶点之间有路径，就称这俩个顶点是连通的。如果无向图任意两个顶点是连通的就称图为连通图\n极大连通子图（连通分量）：该连通子图包含所有边\n极小连通子图：在保证连通情况下边最少的子图\n强连通图：在有向图中，如果顶点m到顶点n有路径存在且n到m也有路径存在，就称这俩个顶点是强连通的，该图就是强连通图\n强连通分量：有向图中的极大强连通子图为强连通分量\n生成树：连通图中包含所有顶点的极小连通子图\n网：在图中每条边都可以标上具有某个意义的数值，称该边的权值，边上带权值的图为网\n图的存储方式\n领接矩阵法、邻接表法、十字链表法、邻接多重表法"
