    "cat": "数据结构",
    "q": "设一棵二叉树的先序序列： A B D F C E G H ，中序序列： B F D A G E H C\n= 1 \\* GB3 画出这棵二叉树。\n= 2 \\* GB3 画出这棵二叉树的后序线索树。\n= 3 \\* GB3 将这棵二叉树转换成对应的树（或森林）。",
