    "q": "已知如图6.33所示的无向网，请给出：\n= 1 \\* GB3 邻接矩阵；\n= 2 \\* GB3 邻接表；\n= 3 \\* GB3 最小生成树",
    "a": "= 1 \\* GB3 = 3 \\* GB3\n\n= 2 \\* GB3\n\na | | b | 4 | | c | 3 | | | | | | | | | | | | | | b | | a | 4 | | c | 5 | | d | 5 | | e | 9 | | | | | | | | c | | a | 3 | | b | 5 | | d | 5 | | h | 5 | | | | | | | | d | | b | 5 | | c | 5 | | e | 7 | | f | 6 | | g | 5 | | h | 4 | | e | | b | 9 | | d | 7 | | f | 3 | | | | | | | | | | | f | | d | 6 | | e | 3 | | g | 2 | | | | | | | | | | | g | | d | 5 | | f | 2 | | h | 6 | | | | | | | | | | |"
