    "cat": "数据结构",
    "q": "已知二叉树T的结点形式为（lling,data,count,rlink），在树中查找值为X的结点，若找到，则记数（count）加1，否则，作为一个新结点插入树中，插入后仍为二叉排序树，写出其非递归算法。",
    "a": "[算法描述]\nvoid SearchBST(BiTree &T,int target){\nBiTree s,q,f; //以数据值target,新建结点s\ns=new BiTNode;\ns->data.x=target;\ns->data.count=0;\ns->lchild=s->rchild=NULL;\n\nif(!T){\nT=s;\nreturn ;\n} //如果该树为空则跳出该函数\nf=NULL;\nq=T;\nwhile (q){\nif (q->data.x==target){\nq->data.count++;\nreturn ;\n} //如果找到该值则计数加一\nf=q;\nif (q->data.x>target) //如果查找值比目标值大，则为该树左孩子\nq=q->lchild;\nelse //否则为右孩子\nq=q->rchild;\n} //将新结点插入树中\nif(f->data.x>target)\nf->lchild=s;\nelse\nf->rchild=s;\n}"
