    "q": "分别写出在散列表中插入和删除关键字为K的一个记录的算法，设散列函数为H，解决冲突的方法为链地址法。",
    "a": "[算法描述]\nbool insert(){\nint data;\ncin>>data;\nint ant=hash(data);\nLinkList p=HT[ant]; //初始化散列表\nwhile (p->next){\nif(p->next->data==data)\nreturn false;\np=p->next;\n} //找到插入位置\nLinkList s;\ns=new LNode;\ns->data=data;\ns->next=p->next;\np->next=s; //插入该结点\nreturn true;\n}\n\nbool deletes(){\nint data;\ncin>>data;\nint ant=hash(data);\nLinkList p=HT[ant]; //初始化散列表\nwhile (p->next){\nif(p->next->data==data){\nLinkList s=p->next;\np->next=s->next;\ndelete s; //删除该结点\nreturn true;\n} //找到删除位置\np=p->next； //遍历下一个结点\n}\nreturn false;\n}"
